
/**
 * File Name: user.repository.ts
 * Description: Handles MongoDB persistence operations for users.
 * Author: Keefe Chen
 */

import { User, type UserRecord } from "./user.model.js";

import type {
  CreateUserInput,
  UpdateOwnProfileInput,
} from "./user.types.js";

export const userRepository = {
  /**
   * Creates a new user account.
   *
   * The passwordHash must be generated by the authentication
   * service before this method is called.
   */
  async create(input: CreateUserInput): Promise<UserRecord> {
    const createdUser = await User.create({
      name: input.name.trim(),
      email: input.email.trim().toLowerCase(),
      passwordHash: input.passwordHash,
      role: input.role ?? "user",
      status: input.status ?? "pending",
    });

    return createdUser.toObject() as UserRecord;
  },

  /**
   * Finds a user using their UUID.
   *
   * Deactivated accounts are excluded.
   * passwordHash remains excluded by the schema's select: false.
   */
  async findById(userId: string): Promise<UserRecord | null> {
    return User.findOne({
      _id: userId,
      deletedAt: null,
    })
      .lean<UserRecord>()
      .exec();
  },

  /**
   * Finds an active user using their UUID and retrieves
   * their password hash for password verification.
   */
  async findByIdWithPassword(
    userId: string
  ): Promise<UserRecord | null> {
    return User.findOne({
      _id: userId,
      status: "active",
      deletedAt: null,
    })
      .select("+passwordHash")
      .lean<UserRecord>()
      .exec();
  },

  /**
   * Finds a user by their normalised email address.
   *
   * Explicitly selects passwordHash for authentication.
   */
  async findByEmail(email: string): Promise<UserRecord | null> {
    return User.findOne({
      email: email.trim().toLowerCase(),
      deletedAt: null,
    })
      .select("+passwordHash")
      .lean<UserRecord>()
      .exec();
  },

  /**
   * Checks whether an email address is already registered.
   *
   * Includes deactivated accounts because their email addresses
   * remain reserved under the unique email constraint.
   */
  async existsByEmail(email: string): Promise<boolean> {
    const user = await User.exists({
      email: email.trim().toLowerCase(),
    });

    return user !== null;
  },

  /**
   * Updates permitted profile information.
   *
   * Only active accounts can update their own profiles.
   */
  async updateOwnProfile(
    userId: string,
    input: UpdateOwnProfileInput
  ): Promise<UserRecord | null> {
    return User.findOneAndUpdate(
      {
        _id: userId,
        status: "active",
        deletedAt: null,
      },
      {
        $set: input,
      },
      {
        new: true,
        runValidators: true,
      }
    )
      .select("-passwordHash")
      .lean<UserRecord>()
      .exec();
  },

  /**
   * Updates the timestamp of the user's last successful login.
   */
  async updateLastLogin(
    userId: string,
    at: Date = new Date()
  ): Promise<void> {
    await User.updateOne(
      {
        _id: userId,
        status: "active",
        deletedAt: null,
      },
      {
        $set: {
          lastLoginAt: at,
        },
      }
    ).exec();
  },

  /**
   * Soft-deactivates a user account.
   *
   * Preserves the user's existing records while preventing
   * the account from being used as an active account.
   */
  async deactivateAccount(userId: string): Promise<boolean> {
    const result = await User.updateOne(
      {
        _id: userId,
        status: "active",
        deletedAt: null,
      },
      {
        $set: {
          status: "disabled",
          deletedAt: new Date(),
        },
      },
      {
        runValidators: true,
      }
    ).exec();

    return result.modifiedCount === 1;
  },
};
